export class ModalVehiculoCtrl{static $inject=["$http","$uibModalInstance","formulario","params"];constructor($http,$uibModalInstance,_form,_params){this.$http=$http,this.$uibModalInstance=$uibModalInstance,this._form=_form,this._params=_params,this.tipoRegistro=1,this.data={}}$onInit(){this._params&&(this.tipoRegistro=2,this.data=this._params)}saveUpdate(){let tituloToast=1==this.tipoRegistro?"Guardar":"Actualizar",posicionToast="toast-top-right";if(this._form.campo(this.data.placa))return void toastr.warning("Ingrese la Placa",tituloToast,posicionToast);if(this._form.campo(this.data.marca))return void toastr.warning("Ingrese la Marca",tituloToast,posicionToast);if(this._form.campo(this.data.modelo))return void toastr.warning("Ingrese el Modelo",tituloToast,posicionToast);const url=1==this.tipoRegistro?"/Vehiculo/Post":"/Vehiculo/Put?id="+this.data.idVehiculo;this.$http.post(url,this.data).then(({data:response})=>{"0"!==response.id?"1"===response.id&&(toastr.success(response.message,response.titleSms,posicionToast),this.$uibModalInstance.close(response)):toastr.warning(response.message,response.titleSms,posicionToast)})}closeModal(){this.$uibModalInstance.close()}}